(() => {const $=id=>document.getElementById(id);let users=[];
async function api(body,action=''){const r=await fetch('/painel/api/users'+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Não foi possível concluir.');return d;}
function reset(){$('user-form').reset();$('user-id').value='';$('active').checked=true;$('form-title').textContent='Cadastrar colaborador';}reset();
async function load(){try{users=(await api()).users;$('users').replaceChildren();for(const u of users){const row=document.createElement('article');row.className='contact';const text=document.createElement('p');text.textContent=u.name+' · '+u.username+' · C · '+(u.active?'Ativo':'Inativo');const b=document.createElement('button');b.type='button';b.className='btn light';b.textContent='Editar';b.addEventListener('click',()=>{$('user-id').value=u.id;$('name').value=u.name;$('username').value=u.username;$('active').checked=!!u.active;$('form-title').textContent='Editar colaborador';$('name').focus();});const resetButton=document.createElement('button');resetButton.type='button';resetButton.className='btn light';resetButton.textContent='Redefinir senha para 1234';resetButton.addEventListener('click',async()=>{if(!confirm('Redefinir a senha de '+u.name+' para 1234? As sessões serão encerradas e a troca será obrigatória.'))return;resetButton.disabled=true;try{await api({id:u.id},'/reset-password');await load();$('feedback').textContent='Senha redefinida para 1234. Troca obrigatória no próximo acesso.';}catch(error){$('feedback').textContent=error.message;}finally{resetButton.disabled=false;}});row.append(text,b,resetButton);$('users').append(row);}if(!users.length)$('users').textContent='Nenhum colaborador cadastrado.';}catch(e){$('feedback').textContent=e.message;}}
$('cancel').addEventListener('click',reset);$('user-form').addEventListener('submit',async e=>{e.preventDefault();e.submitter.disabled=true;try{await api({id:$('user-id').value||undefined,name:$('name').value,username:$('username').value,active:$('active').checked,role:'C'});reset();await load();$('feedback').textContent='Colaborador salvo. Novos usuários entram com 1234 e devem alterar a senha.';}catch(error){$('feedback').textContent=error.message;}finally{e.submitter.disabled=false;}});$('panel-link').hidden=false;load();})();